const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Antarctic region
  const antarctic = ee.Geometry.Polygon(
    [[[-180, -60], [180, -60], [180, -90], [-180, -90], [-180, -60]]],
    null, false
  );

  // Dates
  const date1 = '2021-01-01';
  const date2 = '2021-10-07';

  // Get Sentinel-5P ozone data
  const ozoneCol = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_O3')
    .select('O3_column_number_density')
    .filterBounds(antarctic);

  // Get data for January 1, 2021
  const jan_col = ozoneCol.filterDate('2021-01-01', '2021-01-02');
  const jan_size = jan_col.size().getInfo();
  console.log('January 1 images:', jan_size);

  if (jan_size === 0) {
    console.log('No data for January 1, 2021');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get data for October 7, 2021
  const oct_col = ozoneCol.filterDate('2021-10-07', '2021-10-08');
  const oct_size = oct_col.size().getInfo();
  console.log('October 7 images:', oct_size);

  if (oct_size === 0) {
    console.log('No data for October 7, 2021');
    console.log('<answer>C1</answer>');
    return;
  }

  // Create mosaics
  const jan_img = jan_col.mean();
  const oct_img = oct_col.mean();

  // Convert to Dobson Units (multiply by 2241.15)
  const jan_ozone = jan_img.multiply(2241.15);
  const oct_ozone = oct_img.multiply(2241.15);

  // Define ozone hole: areas where ozone < 220 DU
  const jan_hole = jan_ozone.lt(220);
  const oct_hole = oct_ozone.lt(220);

  // Calculate area of ozone hole in square km
  const pixelArea = ee.Image.pixelArea().divide(1e6);

  const jan_area_result = jan_hole.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: antarctic,
    scale: 5000,
    maxPixels: 1e9
  });

  const oct_area_result = oct_hole.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: antarctic,
    scale: 5000,
    maxPixels: 1e9
  });

  const jan_area = jan_area_result.get('O3_column_number_density').getInfo();
  const oct_area = oct_area_result.get('O3_column_number_density').getInfo();

  console.log('January 1, 2021 ozone hole area (km²):', jan_area);
  console.log('October 7, 2021 ozone hole area (km²):', oct_area);

  // Validate results
  if (jan_area === null || oct_area === null) {
    console.log('Calculation failed - null result');
    console.log('<answer>C3</answer>');
    return;
  }

  if (isNaN(jan_area) || isNaN(oct_area)) {
    console.log('Calculation failed - NaN result');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare areas
  if (oct_area > jan_area) {
    console.log('October ozone hole is larger');
    console.log('<answer>A</answer>');
  } else {
    console.log('October ozone hole is not larger');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
